CREATE OR REPLACE FUNCTION public.candidato_aceita_respostas(_candidato_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.candidatos c WHERE c.id = _candidato_id AND c.created_at > now() - interval '2 hours');
$$;
REVOKE ALL ON FUNCTION public.candidato_aceita_respostas(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.candidato_aceita_respostas(uuid) TO anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.form_aceita_envio(_form_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.forms f WHERE f.id = _form_id AND f.is_active IS TRUE);
$$;
REVOKE ALL ON FUNCTION public.form_aceita_envio(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.form_aceita_envio(uuid) TO anon, authenticated, service_role;

ALTER POLICY "candidatos_anon_select_own" ON public.candidatos TO anon USING (created_at > now() - interval '5 minutes');
ALTER POLICY "candidato_respostas_anon_insert" ON public.candidato_respostas TO anon WITH CHECK (candidato_id IS NOT NULL AND public.candidato_aceita_respostas(candidato_id));
ALTER POLICY "anon_insert_form_submissions" ON public.form_submissions TO anon WITH CHECK (form_id IS NOT NULL AND public.form_aceita_envio(form_id));
ALTER POLICY "insert_only" ON public.exercicio_pre_aula TO anon WITH CHECK (tarefas IS NOT NULL AND jsonb_typeof(tarefas) IN ('array','object') AND octet_length(tarefas::text) <= 50000);

